//! The 5x7 pixel font, its icons and the bigger button icons.
//! Generated from `blip/sprites.py` by `python rust/tools/gen_pixfont.py`; do not edit by hand.

/// Rows of a 5x7 glyph, top to bottom; bit 0x10 is the leftmost pixel.
pub fn glyph(c: char) -> [u8; 7] {
    match c {
        ' ' => [0, 0, 0, 0, 0, 0, 0],
        '!' => [4, 4, 4, 4, 4, 0, 4],
        '#' => [10, 10, 31, 10, 31, 10, 10],
        '%' => [24, 25, 2, 4, 8, 19, 3],
        '&' => [12, 18, 20, 8, 21, 18, 13],
        '\'' => [12, 4, 8, 0, 0, 0, 0],
        '(' => [2, 4, 8, 8, 8, 4, 2],
        ')' => [8, 4, 2, 2, 2, 4, 8],
        '+' => [0, 4, 4, 31, 4, 4, 0],
        ',' => [0, 0, 0, 0, 12, 4, 8],
        '-' => [0, 0, 0, 31, 0, 0, 0],
        '.' => [0, 0, 0, 0, 0, 12, 12],
        '/' => [0, 1, 2, 4, 8, 16, 0],
        '0' => [14, 17, 19, 21, 25, 17, 14],
        '1' => [4, 12, 4, 4, 4, 4, 14],
        '2' => [14, 17, 1, 2, 4, 8, 31],
        '3' => [31, 2, 4, 2, 1, 17, 14],
        '4' => [2, 6, 10, 18, 31, 2, 2],
        '5' => [31, 16, 30, 1, 1, 17, 14],
        '6' => [6, 8, 16, 30, 17, 17, 14],
        '7' => [31, 1, 2, 4, 8, 8, 8],
        '8' => [14, 17, 17, 14, 17, 17, 14],
        '9' => [14, 17, 17, 15, 1, 2, 12],
        ':' => [0, 12, 12, 0, 12, 12, 0],
        '<' => [2, 4, 8, 16, 8, 4, 2],
        '=' => [0, 0, 31, 0, 31, 0, 0],
        '>' => [8, 4, 2, 1, 2, 4, 8],
        '?' => [14, 17, 1, 2, 4, 0, 4],
        '@' => [14, 17, 23, 21, 23, 16, 14],
        'A' => [14, 17, 17, 17, 31, 17, 17],
        'B' => [30, 17, 17, 30, 17, 17, 30],
        'C' => [14, 17, 16, 16, 16, 17, 14],
        'D' => [28, 18, 17, 17, 17, 18, 28],
        'E' => [31, 16, 16, 30, 16, 16, 31],
        'F' => [31, 16, 16, 30, 16, 16, 16],
        'G' => [14, 17, 16, 23, 17, 17, 15],
        'H' => [17, 17, 17, 31, 17, 17, 17],
        'I' => [14, 4, 4, 4, 4, 4, 14],
        'J' => [7, 2, 2, 2, 2, 18, 12],
        'K' => [17, 18, 20, 24, 20, 18, 17],
        'L' => [16, 16, 16, 16, 16, 16, 31],
        'M' => [17, 27, 21, 21, 17, 17, 17],
        'N' => [17, 17, 25, 21, 19, 17, 17],
        'O' => [14, 17, 17, 17, 17, 17, 14],
        'P' => [30, 17, 17, 30, 16, 16, 16],
        'Q' => [14, 17, 17, 17, 21, 18, 13],
        'R' => [30, 17, 17, 30, 20, 18, 17],
        'S' => [15, 16, 16, 14, 1, 1, 30],
        'T' => [31, 4, 4, 4, 4, 4, 4],
        'U' => [17, 17, 17, 17, 17, 17, 14],
        'V' => [17, 17, 17, 17, 17, 10, 4],
        'W' => [17, 17, 17, 21, 21, 21, 10],
        'X' => [17, 17, 10, 4, 10, 17, 17],
        'Y' => [17, 17, 17, 10, 4, 4, 4],
        'Z' => [31, 1, 2, 4, 8, 16, 31],
        '_' => [0, 0, 0, 0, 0, 0, 31],
        c if c.is_ascii_lowercase() => glyph(c.to_ascii_uppercase()),
        _ => [14, 17, 1, 2, 4, 0, 4],
    }
}

/// A named icon (same names as the Python ICON table).
pub fn icon(name: &str) -> [u8; 7] {
    match name {
        "bell" => [4, 14, 14, 14, 31, 0, 4],
        "check" => [0, 1, 3, 22, 28, 8, 0],
        "chevron" => [0, 8, 4, 2, 4, 8, 0],
        "clean" => [12, 18, 18, 12, 0, 3, 3],
        "dnd" => [14, 17, 17, 31, 17, 17, 14],
        "gear" => [4, 21, 14, 27, 14, 21, 4],
        "globe" => [14, 21, 31, 21, 31, 21, 14],
        "hangup" => [0, 14, 31, 27, 17, 0, 0],
        "heart" => [0, 10, 31, 31, 14, 4, 0],
        "hourglass" => [31, 17, 10, 4, 10, 17, 31],
        "coin" => [14, 31, 27, 27, 27, 31, 14],
        "shop" => [4, 10, 31, 17, 21, 17, 31],
        "pick" => [14, 21, 4, 4, 4, 4, 4],
        "gift" => [10, 4, 31, 21, 31, 21, 31],
        "info" => [4, 0, 12, 4, 4, 14, 0],
        "list" => [0, 23, 0, 23, 0, 23, 0],
        "mail" => [0, 31, 27, 21, 17, 31, 0],
        "meal" => [10, 21, 10, 0, 31, 31, 14],
        "mic" => [14, 14, 14, 14, 17, 14, 4],
        "micoff" => [30, 15, 14, 6, 19, 14, 5],
        "moon" => [14, 28, 24, 24, 24, 28, 14],
        "note" => [31, 17, 23, 17, 23, 17, 31],
        "open" => [15, 3, 5, 9, 16, 0, 0],
        "pause" => [27, 27, 27, 27, 27, 27, 0],
        "paw" => [10, 21, 0, 14, 31, 31, 14],
        "people" => [10, 10, 0, 27, 27, 27, 0],
        "phone" => [0, 24, 24, 16, 11, 7, 0],
        "pill" => [6, 15, 31, 30, 12, 0, 0],
        "play" => [0, 14, 23, 31, 31, 31, 14],
        "playtri" => [8, 12, 14, 15, 14, 12, 8],
        "plus" => [0, 4, 4, 31, 4, 4, 0],
        "power" => [4, 21, 21, 17, 17, 14, 0],
        "reset" => [13, 19, 23, 16, 16, 17, 14],
        "snack" => [14, 27, 31, 23, 31, 14, 0],
        "speaker" => [2, 6, 30, 30, 30, 6, 2],
        "stopwatch" => [14, 4, 14, 21, 23, 17, 14],
        "task" => [4, 21, 14, 31, 14, 21, 4],
        "trash" => [4, 31, 0, 31, 21, 21, 14],
        "update" => [4, 4, 21, 14, 4, 0, 31],
        "user" => [14, 14, 14, 0, 31, 31, 31],
        "walk" => [24, 24, 0, 3, 3, 0, 24],
        "x" => [17, 10, 4, 10, 17, 0, 0],
        _ => [14, 17, 1, 2, 4, 0, 4],
    }
}

/// Bigger icons as rows of 0/1.
pub fn big(name: &str) -> &'static [&'static str] {
    match name {
        "chat" => &["01111111110", "11111111111", "11011011011", "11111111111", "01111111110", "01110000000", "01100000000", "01000000000"],
        "globe" => &["0011100", "0101010", "1111111", "1010101", "1111111", "0101010", "0011100"],
        "phone" => &["011000000", "111100000", "111000000", "011000000", "011000000", "001100010", "000111111", "000011111", "000000110"],
        _ => &[],
    }
}

/// Width in pixels of pixel text drawn with cells of `px` (5 wide + 1 gap per character).
pub fn text_width(text: &str, px: i32) -> i32 {
    (text.chars().count() as i32 * 6 - 1).max(0) * px
}
